INSERT INTO appendices (lang_id, code, title, snippet) VALUES 
(1, 1, 'One of the Great Miracles [74:35]', 'Every element of the Quran is mathematically composed - the suras, the verses, the words, the number of certain letters, the number of words from the same root, the number and variety of divine names, the unique spelling of certain words, the absence or deliberate alteration of certain letters within certain words, and many other elements of the Quran besides its content...'), (1, 2, 'God''s Messenger of the Covenant [3:81]', 'His mission is to purify and unify all existing religions into one: Islam (Submission)...'), (1, 3, 'We Made the Quran Easy [54:17]', 'Memorization of the Quran has played a vital role in preserving the original text generation after generation at a time when written books were a rarity...'), (1, 4, 'Why Was the Quran Revealed in Arabic?', 'We learn from 41:44 that the sincere believers have access to the Quran, regardless of their mother tongue...'), (1, 5, 'Heaven and Hell', 'The descriptions of Heaven and Hell throughout the Quran are allegorical...'), (1, 6, 'Greatness of God', 'We learn from Verse 39:67 that God''s greatness is far beyond human comprehension - the verse states that all seven universes are ''folded within God''s hand.''...'), (1, 7, 'Why Were We Created?', 'We are in this world because we committed a horrendous crime, and this life is our chance to redeem ourselves, denounce our crime, and rejoin God''s kingdom...'), (1, 8, 'The Myth of Intercession', 'To believe that anyone, other than God, can intercede on our behalf to have our sins forgiven or our wishes fulfilled, is to set up partners with God. This is idolatry...'), (1, 9, 'Abraham: Original Messenger of Submission', 'One of the prevalent myths is that Muhammad was the founder of Islam...'), (1, 10, 'God''s Usage of the Plural Tense', 'Whenever the first person plural form is used by the Almighty, it invariably indicates participation of other entities, such as the angels...'), (1, 11, 'The Day of Resurrection', 'The earth will shine with the light of God (39:69) as He comes to our universe, together with the angels (89:22)...'), (1, 12, 'Role of the Prophet Muhammad', 'The Prophet''s sole mission was to deliver Quran, the whole Quran, and nothing but Quran (3:20; 5:48-50, 5:92, 5:99; 6:19; 13:40; 16:35, 16:82; 24:54; 29:18; 42:48; 64:12)...'), (1, 13, 'The First Pillar of Submission', 'Verse 3:18 states the First Pillar of Islam (Submission): ''God bears witness that there is no other god besides Him, and so do the angelsand those who possess knowledge.''...'), (1, 14, 'Predestination', 'God fully knows what kind of decision each of us is destined to make; He knows which of us are going to Heaven and which are going to Hell...'), (1, 15, 'Religious Duties: Gift from God', 'When Abraham implored God in 14:40, he did not ask for wealth or health; the gift he implored for was: ''Please God, make me one who observes the contact prayers (Salat).''...'), (1, 16, 'Dietary Prohibition', 'The Quran teaches that God is extremely displeased with those who prohibit anything that was not specifically prohibited in the Quran (16:112-116)...'), (1, 17, 'Death', 'At the moment of death, everyone knows his or her destiny; Heaven or Hell....'), (1, 18, 'Quran is All You Need', 'The Quran proclaims that the Quran is complete, perfect, and fully detailed (6:19, 38, 114, 115; 50:45), and that religious regulations not specifically instituted in the Quran constitute a religion other than Islam, i.e., Submission (42:21, 17:46)...'), (1, 19, 'Hadith and Sunna: Satanic Innovations', 'The Quran informs us that some enemies of the Prophet, described as ''human and jinn devils,'' will fabricate lies and attribute them to the Prophet (6:112, 25:31)...'), (1, 20, 'Quran: Unlike Any Other Book', 'The Quran is God''s Final Testament to the world, and He has pledged to protect it from the slightest distortion (15:9)...'), (1, 21, 'Satan: Fallen Angel', 'The Quran clearly states that Satan was an angel, by virtue of the immense powers and rank bestowed upon him...'), (1, 22, 'Jesus', 'The Quran, informs us that Jesus was a human messenger of God whose sole mission was to deliver God''s message; he never possessed any power, and is now dead (4:171, 5:75, 5:117)...'), (1, 23, 'Chronological Order of Revelation', 'Chronological Sequence of Revelation...'), (1, 24, 'Two False Verses Removed from the Quran', 'A superhuman mathematical system pervades the Quran and serves to guard and authenticate every element in it...'), (1, 25, 'End of the World', 'The Quran provides many signs, and states that the means for unveiling the end of the world have been given (47:18)...'), (1, 26, 'The Three Messengers of Islam', '...it is mathematically coded into the Quran that Abraham, Muhammad, and Rashad are the three messengers of Islam (Submission)...'), (1, 27, 'Who Is Your God?', '...most of these people will be shocked to find out that their proclamation that their god is the Creator of the heavens and the earth is no more than lip service, and that they are in fact destined for Hell (12:106)...'), (1, 28, 'Muhammad Wrote God''s Revelations With His Own Hand', 'The Quran tells us that Muhammad wrote down the Quran - Muhammad''s contemporaries are quoted as saying, [Quran 25:5] They also said, ''Tales from the past that he wrote down; they were dictated to him day and night.''...'), (1, 29, 'The Missing Basmalah', 'This conspicuous absence of the Basmalah from Sura 9 has been an intriguing feature of the Quran for 14 centuries...'), (1, 30, 'Polygamy', 'Polygamy is permitted in the Quran, but under strictly observed circumstances...'), (1, 31, 'Evolution: A Divinely Guided Process', 'Humans are not descendants of monkeys...'), (1, 32, 'The Crucial Age of 40', 'At what age will the human being be held responsible for his or her beliefs?...'), (1, 33, 'Why Did God Send a Messenger Now?', 'As stated in 3:81, and in Appendix 2, God has sent a messenger to consolidate the messages delivered by all the prophets, purify them, and unify them into one religion: Submission...'), (1, 34, 'Virginity/Chastity: A Trait of the True Believers', 'Sons and daughters of the believers must be taught that their happiness throughout their lives depends on following God''s law and preserving their chastity...'), (1, 35, 'Drugs & Alcohol', 'There is no compromise whatsoever regarding illicit drugs and alcoholic beverages; they are called: abominations and the work of Satan (5:90)...'), (1, 36, 'What Price A Great Nation', 'A nation that upholds God''s laws is guaranteed prominence among the nations of the world, victory, prosperity, and happiness (10:62-64, 16:97, 24:55, 41:30-31)...'), (1, 37, 'Criminal Justice in Islam', 'The Quran solves this problem, as well as the problems associated with the criminal justice systems prevalent in today''s world...'), (1, 38, 'The Creator''s Signature', 'This divine stamp appears throughout the universe in much the same manner as the signature of Michelangelo and Picasso identify their works...')
